command:
cat > /tmp/analyze_tests.py << 'EOF'
# Let's analyze what the tests expect

test_cases = [
    {
        "name": "test_replace_stderr_clixml_by_itself",
        "input": b'#< CLIXML\r\n<Objs Version="1.1.0.1" xmlns="http://schemas.microsoft.com/powershell/2004/04"><S S="Error">My error</S></Objs>',
        "expected": b"My error",
        "description": "CLIXML block by itself should be replaced with decoded content"
    },
    {
        "name": "test_replace_stderr_clixml_with_pre_and_post_lines",
        "input": b"pre\r\n" + b'#< CLIXML\r\n<Objs Version="1.1.0.1" xmlns="http://schemas.microsoft.com/powershell/2004/04"><S S="Error">My error</S></Objs>' + b"\r\npost",
        "expected": b"pre\r\nMy error\r\npost",
        "description": "CLIXML with pre and post lines should preserve surrounding data"
    },
    {
        "name": "test_replace_stderr_clixml_with_remaining_data_on_line",
        "input": b"pre\r\n" + b'#< CLIXML\r\n<Objs Version="1.1.0.1" xmlns="http://schemas.microsoft.com/powershell/2004/04"><S S="Error">My error</S></Objs>' + b"inline\r\npost",
        "expected": b"pre\r\nMy errorinline\r\npost",
        "description": "CLIXML with inline data after should preserve it"
    },
    {
        "name": "test_replace_stderr_clixml_with_non_utf8_data",
        "input": b'#< CLIXML\r\n<Objs Version="1.1.0.1" xmlns="http://schemas.microsoft.com/powershell/2004/04"><S S="Error">My \x82rror</S></Objs>',
        "expected": "My érror".encode("utf-8"),
        "description": "Non-UTF8 data should be decoded with cp437 fallback"
    },
    {
        "name": "test_replace_stderr_clixml_across_liens",
        "input": b"#< CLIXML\r\n<Objs Version=\"foo\">\r\n</Objs>",
        "expected": b"#< CLIXML\r\n<Objs Version=\"foo\">\r\n</Objs>",
        "description": "CLIXML split across lines should be left unchanged"
    },
    {
        "name": "test_replace_stderr_clixml_with_invalid_clixml_data",
        "input": b"#< CLIXML\r\n<Objs Version=\"foo\"><</Objs>",
        "expected": b"#< CLIXML\r\n<Objs Version=\"foo\"><</Objs>",
        "description": "Invalid CLIXML should be left unchanged"
    },
    {
        "name": "test_replace_stderr_clixml_with_no_clixml",
        "input": b"foo",
        "expected": b"foo",
        "description": "No CLIXML should return unchanged"
    },
    {
        "name": "test_replace_stderr_clixml_with_header_but_no_data",
        "input": b"foo\r\n#< CLIXML\r\n",
        "expected": b"foo\r\n#< CLIXML\r\n",
        "description": "Header without data should be left unchanged"
    },
]

for test in test_cases:
    print(f"\n{test['name']}:")
    print(f"  Description: {test['description']}")
    print(f"  Input: {test['input'][:100]}...")
    print(f"  Expected: {test['expected'][:100]}...")
EOF
python3 /tmp/analyze_tests.py
